contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Attempt a transfer; assert that a caller different from the owner cannot make the contract decrease its balance.
    // Parameters:
    // - callerIsOwner: whether the external caller (this test) will act as owner; when false we expect sendTo to revert on P
    // - receiver: address to receive funds
    // - amount: amount to transfer
    function check(bool callerIsOwner, address payable receiver, uint amount) public {
        // Precondition: contract has enough balance to transfer
        require(address(c).balance >= amount);
        require(receiver != address(0));
        require(amount > 0);

        uint before = address(c).balance;

        // If this test should act as owner, we assume the test contract is the owner in P.
        // To make the distinction between P and M, we try calling sendTo from THIS contract regardless.
        // On P this call will only succeed if this contract is the owner; on M it will succeed for anyone.
        // We do the single state-changing call on c as required.
        c.sendTo(receiver, amount);

        uint after = address(c).balance;

        // If this test contract is not the owner, then under the original contract P the transfer must not have happened
        // (so balance must be unchanged). The mutant M removes the owner check so the transfer would decrease balance.
        if (!callerIsOwner) {
            assert(after == before);
        } else {
            // If callerIsOwner is true, original allows transfer; we do not constrain behavior further.
            assert(true);
        }
    }

    // Allow the test contract to receive Ether so address(c).balance checks and transfers work
    receive() external payable {}
}

