        // make the test caller the owner by using setUp deployer (this contract) as owner
        // The constructor set owner = msg.sender; since setUp used this test contract, this contract is owner
        // Ensure c has enough balance
        vm.deal(address(c), 1 ether);

        // call c.sendTo as the owner (this contract) so requires pass
        bool ok;
        try c.sendTo(receiverAddr, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for the reference contract (which uses transfer), if the receiver reverts on receiving funds,
        // the call to sendTo must revert (ok == false). The mutant using send might not revert (ok == true) when receiver reverts.
        // We assert the property that when the receiver is the Reverter, the call did not succeed.
        // This assertion is true for the reference implementation for all inputs and will fail for the mutant for some inputs.
        if (useReverting) {
            assertTrue(!ok);
        } else {
            // when receiver accepts, call should succeed
            assertTrue(ok);
        }
    }
}

