pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to forward, and whether to use a failing callee or a successful one
    function testFuzz_property(uint256 amount, bool useReverter) public {
        // admissible domain: amount must be > 0 and not exceed contract balance we will fund
        vm.assume(amount > 0);
        // fund the contract with a sufficiently large balance to attempt the send
        vm.deal(address(c), 1 ether);
        // choose callee: either a Reverter (always reverts on receive) or an Acceptor (accepts funds)
        address victim;
        if (useReverter) {
            victim = address(new Reverter());
        } else {
            victim = address(new Acceptor());
        }

        // record balance before calling
        uint256 before = address(c).balance;

        // drive sendTo from the owner (c was deployed by this test contract's address in setUp)
        // c's constructor set owner = msg.sender, which was this test contract at deployment time
        // so we must call as this test contract (default) and send value from c itself using its internal balance
        // call sendTo with the chosen victim and amount; send as a regular external call (no value attached)
        bool ok;
        try c.sendTo(victim, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call: in the reference contract, if the call returns (ok==true) then transfer succeeded and
        // address(c).balance == before - amount. If the call reverted, reference reverts and we would not reach here,
        // so the only reachable cases are: (1) call succeeded and balance decreased by amount.
        // The mutant can return ok==true while NOT decreasing c's balance when the callee reverted but the mutant ignored success.

        // We assert the general rule: if the external call returned (ok == true), then c's balance must have decreased by exactly amount.
        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            // If it reverted, reference would have reverted and test would have caught that; here we simply allow ok==false
            assertTrue(address(c).balance == before);
        }
    }
}

